import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第三册：培养技能 · Lesson 14 A noble gangster","description":"学习 although 与 despite，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 14 A noble gangster","description":"学习 although 与 despite，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 although 与 despite，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 13 It's only me","link":"/life/english/new-concept/book-3/unit-01/lesson-013"},"next":{"text":"第三册：培养技能 · Lesson 15 Fifty pence worth of trouble","link":"/life/english/new-concept/book-3/unit-01/lesson-015"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 13 It's only me","link":"/life/english/new-concept/book-3/unit-01/lesson-013"},"next":{"text":"第三册：培养技能 · Lesson 15 Fifty pence worth of trouble","link":"/life/english/new-concept/book-3/unit-01/lesson-015"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-014.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-014.md"}`),i={name:"life/english/new-concept/book-3/unit-01/lesson-014.md"};function l(s,e,r,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-14-a-noble-gangster" tabindex="-1">第三册：培养技能 · Lesson 14 A noble gangster <a class="header-anchor" href="#第三册-培养技能-·-lesson-14-a-noble-gangster" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 14 A noble gangster&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从矛盾的人物评价入手，练习说明同一个人可能表现出的不同侧面。表达判断时既不因善举忽略伤害，也不把人物写成单一标签。学习让步从句承认一个事实，再说明该事实为什么不能推翻主要结论，形成有层次的人物评论。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>reputation</td><td>/ˌrepjʊˈteɪʃən/</td><td>n.</td><td>名声</td><td>a mixed reputation</td></tr><tr><td>generous</td><td>/ˈdʒenərəs/</td><td>adj.</td><td>慷慨的</td><td>a generous donation</td></tr><tr><td>threat</td><td>/θret/</td><td>n.</td><td>威胁</td><td>a serious threat</td></tr><tr><td>contradiction</td><td>/ˌkɒntrəˈdɪkʃən/</td><td>n.</td><td>矛盾</td><td>an apparent contradiction</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>in spite of — 尽管，后接名词性成分</li><li>be known for — 因某特征而闻名</li></ul><h2 id="语法讲解-although-与-despite" tabindex="-1">语法讲解：although 与 despite <a class="header-anchor" href="#语法讲解-although-与-despite" aria-label="Permalink to &quot;语法讲解：although 与 despite&quot;">​</a></h2><p>although 和 though 后接完整分句，despite 和 in spite of 后接名词、代词或动名词。若 despite 后需要完整分句，可写 despite the fact that。标准书面句里通常不把 although 与 but 同时用于同一对主从句，因为二者都承担转折连接功能。让步结构承认前项真实或暂时接受前项，却说明后项仍然成立；它不同于 because 所表达的原因关系。评议人物时要明确让步的是哪种行为，不要把让步写成对所有行为的免责。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Although the businessman funded a clinic, his illegal methods still harmed the community.</p></blockquote><p>虽然这位商人资助了一家诊所，他的非法手段仍伤害了社区。</p><p>although 从句承认善举，主句保留对手段的评价；still 强化让步关系。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Despite he helped us 结构不完整，应为 Despite helping us 或 Although he helped us。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 although 从句后短停，在主句的 ignored 和 safety 上落重音，听是否能突出作者最终判断。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Although the director created many jobs, she ignored repeated safety complaints. Several workers had to replace damaged equipment themselves. A fair assessment must consider both employment and working conditions.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句评价一位虚构人物，承认贡献，再说明具体问题和判断标准。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>评价建立在两类具体行为上，最后一句明确衡量维度。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>改写：Although she was wealthy, she lived simply.（用 despite）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Despite being wealthy, she lived simply.</p><p><strong>解析：</strong> 介词后用动名词结构。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>例句是否认为资助诊所抵消了伤害？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> 主句明确指出伤害仍存在。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>删除错误连接词：Although it was risky, but he agreed.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Although it was risky, he agreed.</p><p><strong>解析：</strong> 同一结构不重复 although 和 but。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：although 与 despite。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-013">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-015">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=t(i,[["render",l]]);export{u as __pageData,g as default};
